using Fluxer.Core.Media;
using Xunit;

namespace Fluxer.Core.Tests;

public sealed class OpenPgpTests
{
    // A real yt-dlp release's SHA2-256SUMS and SHA2-256SUMS.sig, fetched 2026-10-18.
    private static readonly byte[] Sums = Convert.FromBase64String("");
    private static readonly byte[] Sig = Convert.FromBase64String("");

    [Fact]
    public void RealYtDlpRelease_VerifiesWithThePinnedKey()
    {
        Assert.True(OpenPgp.VerifyDetached(Sums, Sig, OpenPgp.YtDlpKey));
    }

    [Fact]
    public void TamperedSums_OrGarbageSignature_AreRejected()
    {
        var tampered = (byte[])Sums.Clone();
        tampered[10] ^= 1;
        Assert.False(OpenPgp.VerifyDetached(tampered, Sig, OpenPgp.YtDlpKey));
        Assert.False(OpenPgp.VerifyDetached(Sums, [1, 2, 3], OpenPgp.YtDlpKey));
        Assert.False(OpenPgp.VerifyDetached(Sums, [], OpenPgp.YtDlpKey));
    }
}
